await sdk.dm('Alpha', 'Guard got me to 16/22 before I died - likely still hurt. Meet me at north outpost (3205,3380): targets there: Guard(21), Dark wizard(7), Barbarian woman(8), Tramp. You tank guard, I take wizard/barb woman.');
// Walk north to outpost
const r1 = await bot.walkTo(3222, 3280, 4, { timeout: 35000 }).catch(e => String(e).slice(0,60));
const r2 = await bot.walkTo(3205, 3379, 4, { timeout: 90000 }).catch(e => String(e).slice(0,60));
const s = sdk.getState();
return { r1: r1.message?.slice(0,40), r2: r2.message?.slice(0,40), pos: `${s.player.x},${s.player.z}`, hp: s.player.hp, npcs: s.nearbyNpcs.slice(0,8).map(n=>`${n.name} L${n.level} d${n.distance}`) };

const start = Date.now();
let guardIdx = null;
while (Date.now() - start < 75000) {
  await bot.dismissBlockingUI().catch(()=>{});
  const s = sdk.getState();
  if (s.player.isDead) return { died: true };
  // flee at 6 HP to save for wizard/barb
  if (s.player.hp <= 6) { await bot.walkTo(s.player.x, s.player.z + 12, 2, { timeout: 8000 }).catch(()=>{}); return { fled: true, hp: s.player.hp }; }
  const guards = s.nearbyNpcs.filter(n => /^guard$/i.test(n.name));
  if (!guards.length) return { guardsGone: true };
  const g = guards.find(n => n.index === guardIdx) || guards.sort((a,b)=>a.distance-b.distance)[0];
  if (guardIdx !== null && !guards.some(n => n.index === guardIdx)) return { killed: true };
  guardIdx = g.index;
  if (!s.player.combat.inCombat) {
    const res = await bot.attack(g).catch(()=>({success:false}));
    if (res.reason === 'not_attackable') return { notAttackable: true };
  }
  await new Promise(r => setTimeout(r, 500));
}
return { timeout: true, guardHp: sdk.getState().nearbyNpcs.find(n=>/^guard$/i.test(n.name))?.hp, myHp: sdk.getState().player.hp };

await sdk.dm('Alpha', 'Guard at outpost now 16/22, I dealt 6 dmg. Come finish it! Also Tramp + Barb woman (L8) nearby.').catch(()=>{});
const start = Date.now();
while (Date.now() - start < 70000) {
  await bot.dismissBlockingUI().catch(()=>{});
  const s = sdk.getState();
  if (s.player.isDead) return { died: true };
  if (!s.nearbyNpcs.some(n => /^guard$/i.test(n.name) && n.hp !== undefined && n.inCombat)) {
    const anyGuard = s.nearbyNpcs.filter(n => /^guard$/i.test(n.name));
    if (!anyGuard.length || s.player.combat.inCombat === false && !anyGuard.some(n=>n.inCombat)) {
      // guard with hp tag gone => died? check for kill message
      return { guardResolved: true, myHp: s.player.hp, combat: s.player.combat.inCombat };
    }
  }
  if (!s.player.combat.inCombat) {
    const g = s.nearbyNpcs.filter(n => /^guard$/i.test(n.name)).sort((a,b)=>a.distance-b.distance)[0];
    if (g) await bot.attack(g).catch(()=>{});
  }
  await new Promise(r => setTimeout(r, 500));
}
const s2 = sdk.getState();
return { timeout: true, hp: s2.player.hp, guardHp: s2.nearbyNpcs.find(n=>/^guard$/i.test(n.name))?.hp };

