// Final push: attack guard until deadline
const start = Date.now();
while (Date.now() - start < 45000) {
  await bot.dismissBlockingUI().catch(()=>{});
  const s = sdk.getState();
  if (s.player.isDead) return { died: true };
  const g = s.nearbyNpcs.filter(n => /^guard$/i.test(n.name)).sort((a,b)=>a.distance-b.distance)[0];
  if (!g) return { guardGone: true, myHp: s.player.hp };
  if (!s.player.combat.inCombat) await bot.attack(g).catch(()=>{});
  await new Promise(r => setTimeout(r, 400));
}
const s2 = sdk.getState();
return { time: 'up', myHp: s2.player.hp, guard: s2.nearbyNpcs.find(n=>/^guard$/i.test(n.name))?.hp };
